package com.library.ui; import com.library.model.*; import com.library.service.*; import javax.swing.*; import javax.swing.table.DefaultTableModel; import java.awt.*;
public class ReturnBookFrame extends JFrame { private final LibraryService service=new LibraryService();private final MemberService members=new MemberService();private final JTextField search=new JTextField(24);private final JLabel info=new JLabel("Search or select a student to see complete details.");private final DefaultTableModel model=new DefaultTableModel(new String[]{"Transaction","Enrollment No.","Student","Book","Issue","Due","Status"},0){public boolean isCellEditable(int r,int c){return false;}};private final JTable table=new JTable(model); public ReturnBookFrame(){super("Return Book");setSize(1050,640);setMinimumSize(new Dimension(850,540));setLocationRelativeTo(null);setDefaultCloseOperation(DISPOSE_ON_CLOSE);JPanel root=new JPanel(new BorderLayout());root.add(UI.header(this,"Return Book","Search by enrollment, email, phone or name; overdue status refreshes automatically"),BorderLayout.NORTH);JPanel find=new JPanel(new FlowLayout(FlowLayout.LEFT,10,10));find.setBackground(Color.WHITE);find.add(new JLabel("Search student / enrollment"));find.add(search);JButton go=UI.button("Search");go.addActionListener(e->load());find.add(go);root.add(find,BorderLayout.CENTER);UI.table(table);table.getSelectionModel().addListSelectionListener(e->showStudent());JPanel body=new JPanel(new BorderLayout());body.add(new JScrollPane(table),BorderLayout.CENTER);info.setBorder(BorderFactory.createEmptyBorder(10,14,10,14));info.setForeground(UI.NAVY);body.add(info,BorderLayout.SOUTH);JPanel center=new JPanel(new BorderLayout());center.add(find,BorderLayout.NORTH);center.add(body,BorderLayout.CENTER);root.remove(find);root.add(center,BorderLayout.CENTER);JButton returnBook=UI.button("Return Selected Book");returnBook.addActionListener(e->returnBook());JPanel footer=new JPanel(new FlowLayout(FlowLayout.RIGHT,16,12));footer.setBackground(Color.WHITE);footer.add(returnBook);root.add(footer,BorderLayout.SOUTH);add(root);load();} private void load(){try{model.setRowCount(0);for(Transaction t:service.transactions(search.getText()))if(t.getReturnDate()==null)model.addRow(new Object[]{t.getTransactionId(),t.getMemberId(),t.getMemberName(),t.getBookName(),t.getIssueDate(),t.getDueDate(),t.getStatus()});info.setText("Select a row to see complete student details.");}catch(Exception e){UI.error(this,e);}} private void showStudent(){try{int row=table.getSelectedRow();if(row<0)return;Member m=members.get(((Number)model.getValueAt(row,1)).longValue());info.setText("Enrollment: "+m.getMemberId()+"  |  Name: "+m.getName()+"  |  Email: "+m.getEmail()+"  |  Phone: "+m.getPhone()+"  |  Course: "+m.getCourse()+"  |  Department: "+m.getDepartment()+"  |  Semester: "+m.getSemester()+"  |  Status: "+m.getStatus());}catch(Exception e){UI.error(this,e);}} private void returnBook(){try{int row=table.getSelectedRow();if(row<0)throw new IllegalArgumentException("Search and select an active student transaction.");long id=((Number)model.getValueAt(row,0)).longValue();UI.info(this,"Book returned. Fine: "+UI.rupee(service.returnBook(id)));load();}catch(Exception e){UI.error(this,e);}} }
